import{_ as s,o as t,c as o,a4 as e}from"./chunks/framework.DAe4SYBh.js";const g=JSON.parse('{"title":"文件系统分区参考","description":"","frontmatter":{},"headers":[],"relativePath":"goke/common/文件系统分区参考.md","filePath":"goke/common/文件系统分区参考.md"}'),n={name:"goke/common/文件系统分区参考.md"};function i(p,a,r,l,u,d){return t(),o("div",null,[...a[0]||(a[0]=[e(`<h1 id="文件系统分区参考" tabindex="-1">文件系统分区参考 <a class="header-anchor" href="#文件系统分区参考" aria-label="Permalink to “文件系统分区参考”">​</a></h1><p>以调整 rootfs 分区大小，创建 usr、data、appfs 分区，并将原来 rootfs 中的 usr 文件夹移动到 usr 分区为例。</p><p>请根据项目实际情况自行调整 ！！！</p><h2 id="_1-去掉-rootfs-的-usr" tabindex="-1">1. 去掉 rootfs 的 /usr <a class="header-anchor" href="#_1-去掉-rootfs-的-usr" aria-label="Permalink to “1. 去掉 rootfs 的 /usr”">​</a></h2><p>source/rootfs/busybox/Makefile</p><p>在 <code>cp -arf $(BUSYBOX_PREFIX)/. $(ROOTFS_PREFIX) </code> 后面一句</p><p><code>rm -rf $(ROOTFS_PREFIX)/usr</code></p><h2 id="_2-修改-bootargs" tabindex="-1">2. 修改 bootargs <a class="header-anchor" href="#_2-修改-bootargs" aria-label="Permalink to “2. 修改 bootargs”">​</a></h2><p>configs/xm72050510/prebuildts/spi_bootargs_tiny.txt</p><p><code>bootargs</code> 修改分区大小<code>512K(boot),512K(bootargs),4M(kernel),2M(rootfs),512K(usr),512K(data),-(appfs)</code></p><p>完整修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bootcmd=sf probe 0;xmediaapp;boothz 0x41000000 0x40008000 0x20000 0x240000</span></span>
<span class="line"><span>bootargs=mem=128M console=ttyAMA0,115200 root=/dev/mtdblock3 rootfstype=jffs2 rw mtdparts=sfc:128K(boot),128K(bootargs),2304K(kernel),2M(rootfs),512K(usr),512K(data),-(appfs) lpj=9838592</span></span></code></pre></div><h2 id="_3-修改烧录-xml" tabindex="-1">3. 修改烧录 xml <a class="header-anchor" href="#_3-修改烧录-xml" aria-label="Permalink to “3. 修改烧录 xml”">​</a></h2><p>拷贝一份 spi_partitions_tiny.xml，在 FastBurn 中加入和调整自定义分区信息，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot; ?&gt;</span></span>
<span class="line"><span>&lt;Partition_Info&gt;</span></span>
<span class="line"><span>    &lt;Part Select=&quot;1&quot; PartName=&quot;fastboot&quot; StorageMedia=&quot;ddr&quot; ImageFormat=&quot;raw&quot; StartAddr=&quot;0&quot; PartLen=&quot;0&quot; ImagePath=&quot;out\\xm72050510\\image\\spi_image\\bootstrap_xm72050510.bin&quot; /&gt;</span></span>
<span class="line"><span>    &lt;Part Select=&quot;1&quot; PartName=&quot;boot&quot; StorageMedia=&quot;spi-nor&quot; ImageFormat=&quot;raw&quot; StartAddr=&quot;0&quot; PartLen=&quot;128K&quot; ImagePath=&quot;out\\xm72050510\\image\\spi_image\\uboot_xm72050510.bin&quot; /&gt;</span></span>
<span class="line"><span>    &lt;Part Select=&quot;1&quot; PartName=&quot;bootargs&quot; StorageMedia=&quot;spi-nor&quot; ImageFormat=&quot;raw&quot; StartAddr=&quot;128K&quot; PartLen=&quot;128K&quot; ImagePath=&quot;out\\xm72050510\\image\\spi_image\\bootargs.bin&quot; /&gt;</span></span>
<span class="line"><span>    &lt;Part Select=&quot;1&quot; PartName=&quot;kernel&quot; StorageMedia=&quot;spi-nor&quot; ImageFormat=&quot;raw&quot; StartAddr=&quot;256K&quot; PartLen=&quot;2304K&quot; ImagePath=&quot;out\\xm72050510\\image\\spi_image\\kernel_xm72050510&quot; /&gt;</span></span>
<span class="line"><span>    &lt;Part Select=&quot;1&quot; PartName=&quot;rootfs&quot; StorageMedia=&quot;spi-nor&quot; ImageFormat=&quot;jffs2&quot; StartAddr=&quot;2560K&quot; PartLen=&quot;2M&quot; ImagePath=&quot;out\\xm72050510\\image\\spi_image\\rootfs.64k.jffs2&quot; /&gt;</span></span>
<span class="line"><span>    &lt;Part Select=&quot;1&quot; PartName=&quot;usr&quot; StorageMedia=&quot;spi-nor&quot; ImageFormat=&quot;jffs2&quot; StartAddr=&quot;4608K&quot; PartLen=&quot;512K&quot; ImagePath=&quot;out\\xm72050510\\image\\spi_image\\usrfs.jffs2&quot; /&gt;</span></span>
<span class="line"><span>    &lt;Part Select=&quot;1&quot; PartName=&quot;data&quot; StorageMedia=&quot;spi-nor&quot; ImageFormat=&quot;jffs2&quot; StartAddr=&quot;5M&quot; PartLen=&quot;512K&quot; ImagePath=&quot;out\\xm72050510\\image\\spi_image\\datafs.jffs2&quot; /&gt;</span></span>
<span class="line"><span>    &lt;Part Select=&quot;1&quot; PartName=&quot;appfs&quot; StorageMedia=&quot;spi-nor&quot; ImageFormat=&quot;jffs2&quot; StartAddr=&quot;5632K&quot; PartLen=&quot;10752K&quot; ImagePath=&quot;out\\xm72050510\\image\\spi_image\\appfs.jffs2&quot; /&gt;</span></span>
<span class="line"><span>&lt;/Partition_Info&gt;</span></span></code></pre></div><h2 id="_4-创建分区-image" tabindex="-1">4. 创建分区 image <a class="header-anchor" href="#_4-创建分区-image" aria-label="Permalink to “4. 创建分区 image”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 创建分区 image 目录</span></span>
<span class="line"><span>mkdir -p out/xm72050510/usrfs</span></span>
<span class="line"><span>mkdir -p out/xm72050510/datafs</span></span>
<span class="line"><span>mkdir -p out/xm72050510/appfs</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 拷贝内容到分区目录</span></span>
<span class="line"><span>cp -r out/xm72050510/rootfs_builddir/busybox-1_26_2/.install/usr/* out/xm72050510/usrfs/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 创建 jffs2 分区 image</span></span>
<span class="line"><span>mkfs.jffs2 -d out/xm72050510/usrfs/ -l -e 0x10000 -o out/xm72050510/image/spi_image/usrfs.jffs2</span></span>
<span class="line"><span>mkfs.jffs2 -d out/xm72050510/datafs/ -l -e 0x10000 -o out/xm72050510/image/spi_image/datafs.jffs2</span></span>
<span class="line"><span>mkfs.jffs2 -d out/xm72050510/appfs/ -l -e 0x10000 -o out/xm72050510/image/spi_image/appfs.jffs2</span></span></code></pre></div><h2 id="_5-板端启动脚本挂载" tabindex="-1">5. 板端启动脚本挂载 <a class="header-anchor" href="#_5-板端启动脚本挂载" aria-label="Permalink to “5. 板端启动脚本挂载”">​</a></h2><p>将下面内容加入开机启动脚本</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p /appfs</span></span>
<span class="line"><span>mkdir -p /data</span></span>
<span class="line"><span>mkdir -p /usr</span></span>
<span class="line"><span>mount -t jffs2 /dev/mtdblock4 /usr/</span></span>
<span class="line"><span>mount -t jffs2 /dev/mtdblock5 /data/</span></span>
<span class="line"><span>mount -t jffs2 /dev/mtdblock6 /appfs/</span></span></code></pre></div><h2 id="如果要修改-uboot-和-bootargs-分区大小" tabindex="-1">*如果要修改 uboot 和 bootargs 分区大小 <a class="header-anchor" href="#如果要修改-uboot-和-bootargs-分区大小" aria-label="Permalink to “*如果要修改 uboot 和 bootargs 分区大小”">​</a></h2><p>要修改source/bootloader/u-boot-2020.01/configs/xm720xxx_tiny_defconfig 的 <code>CONFIG_ENV_OFFSET</code></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONFIG_ENV_OFFSET=0x20000</span></span></code></pre></div>`,23)])])}const c=s(n,[["render",i]]);export{g as __pageData,c as default};
